import Foundation
import Testing
@testable import FantasyMapCore

/// Compatibility fixtures for saved water maps at format version 1 and algorithm revision 1 (see docs/plans/water-8-saving.md).
///
/// The files in `Fixtures/waterrevision1` are **fixed**: committed once and never regenerated by these tests, so a change to the saved
/// format, the loaded state or the cells rebuilt from the points fails here even if generating and loading changed alike. For each
/// file the manifest names the captured run of the original it was made from, so the loaded flux, river numbers, confluences and
/// packed heights are compared with **the original's own** digests, and holds the digest of the packed cells rebuilt from the points.
///
/// To write them (only deliberately, with a revision bump explained in the commit):
/// `MAP_WRITE_WATER_REVISION1=<folder> swift test --filter WaterRevisionOneFixtureTests/writeTheFixtures`
struct WaterRevisionOneFixtureTests {
	struct Entry: Codable {
		var file: String
		var fileSha256: String
		var seed: String, key: String
		var width: Double, height: Double
		var cellsDesired: Int
		var rain: Double, steps: Int, limit: Double, erosion: Bool
		var packedCells: Int, rivers: Int, lakesWithInlets: Int
		var packedCellStructureSha256: String
	}
	struct Manifest: Codable { var formatVersion: Int; var algorithmRevision: Int; var entries: [Entry] }

	/// Two captured runs of the original: one with erosion, and one of another template without it.
	static func wanted() throws -> [RiverGeneratorTests.Run] {
		let runs = try RiverGeneratorTests().runs().filter { $0.whole != nil && $0.riverCount >= 5 && $0.lakes.contains { ($0.inlets ?? []).count > 1 } }
		let a = try #require(runs.first { $0.erosion && $0.rain == 100 && $0.steps == 250 })
		let b = try #require(runs.first { !$0.erosion && $0.key != a.key })
		return [a, b]
	}

	static func settings(_ run: RiverGeneratorTests.Run) -> WaterSettings {
		var s = WaterSettings()
		s.precipitation = run.rain; s.lakeElevationLimit = run.limit; s.allowErosion = run.erosion; s.resolveDepressionsSteps = run.steps
		return s
	}

	static func folder() throws -> URL { try #require(Bundle.module.url(forResource: "Fixtures/waterrevision1", withExtension: nil)) }

	@Test(.enabled(if: ProcessInfo.processInfo.environment["MAP_WRITE_WATER_REVISION1"] != nil))
	func writeTheFixtures() throws {
		let out = URL(filePath: try #require(ProcessInfo.processInfo.environment["MAP_WRITE_WATER_REVISION1"]))
		var entries: [Entry] = []
		for (i, run) in try Self.wanted().enumerated() {
			let land = try LandMap.generate(seed: run.seed, width: run.width, height: run.height, cellsDesired: run.cellsDesired, template: try #require(HeightmapTemplate.named(run.key)))
			let water = try WaterMap.generate(land: land, settings: Self.settings(run))
			let data = try water.encoded()
			let name = "water-\(i)-\(run.key)-\(run.cellsDesired).json"
			try data.write(to: out.appending(path: name))
			entries.append(Entry(file: name, fileSha256: RevisionOneFixtureTests.sha(data), seed: run.seed, key: run.key, width: run.width, height: run.height, cellsDesired: run.cellsDesired,
				rain: run.rain, steps: run.steps, limit: run.limit, erosion: run.erosion, packedCells: water.packed.points.count, rivers: water.rivers.count,
				lakesWithInlets: water.features.features.filter { !($0.inlets ?? []).isEmpty }.count, packedCellStructureSha256: RevisionOneFixtureTests.cellStructureDigest(water.packed.voronoi)))
		}
		let encoder = JSONEncoder()
		encoder.outputFormatting = [.sortedKeys, .prettyPrinted]
		try encoder.encode(Manifest(formatVersion: SavedWaterMap.currentFormatVersion, algorithmRevision: SavedWaterMap.currentAlgorithmRevision, entries: entries)).write(to: out.appending(path: "manifest.json"))
	}

	@Test func theFixedRevisionOneFilesStillLoadToTheOriginalsStateAndTheSameRebuiltCells() throws {
		let folder = try Self.folder()
		let manifest = try JSONDecoder().decode(Manifest.self, from: Data(contentsOf: folder.appending(path: "manifest.json")))
		#expect(manifest.formatVersion == 1 && manifest.algorithmRevision == 1)
		#expect(SavedWaterMap.currentFormatVersion == 1 && SavedWaterMap.currentAlgorithmRevision == 1, "the format or revision changed: keep revision-1 files readable and add fixtures for the new one")
		let runs = try RiverGeneratorTests().runs()
		#expect(manifest.entries.count == 2)
		for entry in manifest.entries {
			let data = try Data(contentsOf: folder.appending(path: entry.file))
			#expect(RevisionOneFixtureTests.sha(data) == entry.fileSha256, "\(entry.file): the committed file itself is unchanged")
			let water = try WaterMap(decoding: data)
			#expect(try water.encoded() == data, "\(entry.file): re-saving gives the same bytes")
			#expect(water.packed.points.count == entry.packedCells && water.rivers.count == entry.rivers, "\(entry.file): counts")
			#expect(water.features.features.filter { !($0.inlets ?? []).isEmpty }.count == entry.lakesWithInlets && entry.lakesWithInlets > 0)
			#expect(RevisionOneFixtureTests.cellStructureDigest(water.packed.voronoi) == entry.packedCellStructureSha256, "\(entry.file): rebuilt packed cells")
			// the loaded state is the original's own end state for the captured run
			let run = try #require(runs.first { $0.seed == entry.seed && $0.key == entry.key && $0.cellsDesired == entry.cellsDesired && $0.width == entry.width && $0.height == entry.height && $0.rain == entry.rain && $0.steps == entry.steps && $0.limit == entry.limit && $0.erosion == entry.erosion })
			#expect(Fixtures.hashUInt16s(water.flux) == run.sha.fl && Fixtures.hashUInt16s(water.riverIds) == run.sha.r && Fixtures.hashUInt16s(water.confluence) == run.sha.conf && Fixtures.hashBytes(Data(water.packed.heights)) == run.sha.h, "\(entry.file): the original's own flux, rivers, confluences and heights")
			#expect(water.settings == Self.settings(run))
		}
	}
}
